                <div class="os-metric-footnote">${data.issuedCount} issued · 0 to send</div>
            </div>
            <div class="os-metric">
                <div class="os-metric-label">Collected · 2026</div>
                <div class="os-metric-value">${data.collected2026} <span class="os-metric-unit">CHF</span></div>
